	\[
		u \in \ell\bigl(L^{\mathrm{Ln}}_v(u),\, v\bigr)\;.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:line-rep-kernel, def:line}
	By Lemma~\ref{lem:line-rep-kernel} there is $t \in \F_q$ with $u - L^{\mathrm{Ln}}_v(u) = t\,v$, so $u = L^{\mathrm{Ln}}_v(u) + t\,v$, which lies in $\ell\bigl(L^{\mathrm{Ln}}_v(u), v\bigr)$ by Equation~\eqref{eq:line-set}.
\end{proof}

